# Every input and output of this project, on the box's own channels so it
# runs with nothing wired. To use a remote I/O module, declare it and change
# the device on each line, for example:
#   device rio modbus-tcp 192.168.1.50:502 unit=1 timeout_ms=300 poll_ms=20
#   in  part_in bool rio di:0
# Nothing counts until start_pb is pressed or forced. If this box's own
# channels are wired to anything, these lines drive it: check them first.
in  start_pb     bool box di:0
in  stop_pb      bool box di:1
in  part_in      bool box di:2
in  fault_in     bool box di:3
in  reset_pb     bool box di:4
in  new_shift_in bool box di:5
out run_lamp  bool box do:0 safe=false
out idle_lamp bool box do:1 safe=false
out down_lamp bool box do:2 safe=false
out cycles       int  screen cycles safe=0
out shift_cycles int  screen shift_cycles safe=0
out state        int  screen state safe=0
out uptime_pct   real screen uptime_pct unit=%
